"""Make models generated by LocalSpawn (Hunyuan3D + UltraTex GLBs) game-ready for Safe Haven's gathering nodes.

LocalSpawn makes the shape and its colour, normal and ORM maps from a concept image; this does what the game needs on
top (see the asset principles), so AgentScripts/BuildGatheringModels.cs takes the result like any other asset:

- each GLB becomes one look ("<Asset> A", "B", ...): scaled so its widest side is the size given, turned about the
  vertical, its pivot on the ground under its middle, lowest point on the ground;
- two levels of detail ("<look> LOD1", "LOD2", decimated) and a convex "<look> Collider";
- the looks share one texture set: their own maps are baked into a shared atlas (2048), and Height (parallax) and
  BlendMask (curvature, edge wear, cavity, coverage: where the live moss grows) are baked from the mesh (prop_bake.py).

Writes Assets/_Project/Art/Gathering/<Asset>/ (<Asset>.fbx, _Albedo, _Normal, _ORM, _Height, _BlendMask and, with
--glow, _Emission) and a preview render beside the GLBs.

Glowing things (moonsilver, deepstone, the Life Orbs) glow where their albedo is close to a colour or bright
(--glow-json '{"mode": "hue"|"bright", "colour": [r,g,b], "tint": [r,g,b], "threshold": 0-1}'): the generated
textures carry no emission, so it is made from the albedo after the bake.

Run: blender -b --factory-startup --python Tools/Blender/ingest_generated.py -- <project root> <asset name> <width m>
     [--glow-json JSON] [--turn DEG ...] <look A.glb> [<look B.glb> ...]
"""
import json
import math
import os
import sys

import numpy

import bmesh
import bpy
from mathutils import Matrix, Vector

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from prop_bake import *  # noqa: E402,F401,F403
from prop_bake import ROOT, args  # noqa: E402

NAME = args[1]
WIDTH = float(args[2])
rest = args[3:]
GLOW = None
TURNS = []
GLBS = []
i = 0
while i < len(rest):
    if rest[i] == "--glow-json":
        GLOW = json.loads(rest[i + 1])
        i += 2
    elif rest[i] == "--turn":
        TURNS.append(float(rest[i + 1]))
        i += 2
    else:
        GLBS.append(rest[i])
        i += 1


def manifest_max_height():
    """The asset's height cap from Tools/LocalSpawn/gathering_manifest.json (max_height), if it has one."""
    try:
        with open(os.path.join(ROOT, "Tools", "LocalSpawn", "gathering_manifest.json"), encoding="utf-8") as f:
            entry = next((a for a in json.load(f)["assets"] if a["asset"] == NAME), {})
        return entry.get("max_height")
    except (OSError, ValueError):
        return None


MAX_HEIGHT = manifest_max_height()


def manifest_metal_floor():
    """Where the asset's metal starts (manifest metal_floor, 0-1), or None: the asset has no metal at all.
    UltraTex paints metallic onto rock, wood and moss too (Iron's host rock ~0.7, Sticks' wood 1.0), which makes them
    shine like metal; only an ore keeps its metallic, remapped so everything under the floor becomes 0."""
    try:
        with open(os.path.join(ROOT, "Tools", "LocalSpawn", "gathering_manifest.json"), encoding="utf-8") as f:
            entry = next((a for a in json.load(f)["assets"] if a["asset"] == NAME), {})
        return entry.get("metal_floor")
    except (OSError, ValueError):
        return None


METAL_FLOOR = manifest_metal_floor()


def look_value(look_key, key):
    """A per-look manifest setting (looks[i][key] for the look whose key matches), or None."""
    looks = manifest_value("looks") or []
    return next((l.get(key) for l in looks if l.get("key") == look_key), None)


def manifest_value(key):
    try:
        with open(os.path.join(ROOT, "Tools", "LocalSpawn", "gathering_manifest.json"), encoding="utf-8") as f:
            return next((a for a in json.load(f)["assets"] if a["asset"] == NAME), {}).get(key)
    except (OSError, ValueError):
        return None


# How much of the metal taken away from rock under the floor darkens its colour (0-1). A surface at metallic m shows
# its base colour only as reflection; as a matte rock it is lit diffusely by base * (1 - m), so dropping the false metal
# without darkening leaves a pale rock (Iron's host rock went from dark to pale grey).
DIELECTRIC_DARKEN = manifest_value("dielectric_darken") or 0.0
ROUGHNESS = manifest_value("roughness")


def manifest_glow():
    """The asset's glow from the manifest, which wins over --glow-json (it can change while a batch is running)."""
    try:
        with open(os.path.join(ROOT, "Tools", "LocalSpawn", "gathering_manifest.json"), encoding="utf-8") as f:
            return next((a for a in json.load(f)["assets"] if a["asset"] == NAME), {}).get("glow")
    except (OSError, ValueError):
        return None


GLOW = manifest_glow() or GLOW  # the manifest is the source of truth


def import_look(path, key, turn, coll):
    """One GLB as a single mesh object, normalised: widest side WIDTH, pivot on the ground under its middle."""
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=path)
    meshes = [o for o in bpy.data.objects if o not in before and o.type == 'MESH']
    for o in [o for o in bpy.data.objects if o not in before and o.type != 'MESH']:
        bpy.data.objects.remove(o)
    for o in meshes:
        o.matrix_world = o.matrix_world.copy()
        for c in list(o.users_collection):
            c.objects.unlink(o)
        coll.objects.link(o)
    obj = join(meshes, f"{NAME} {key}") if len(meshes) > 1 else meshes[0]
    obj.name = obj.data.name = f"{NAME} {key}"
    select_only([obj])
    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)
    obj.data.transform(Matrix.Rotation(math.radians(turn), 4, 'Z'))
    xs = [v.co.x for v in obj.data.vertices]
    ys = [v.co.y for v in obj.data.vertices]
    zs = [v.co.z for v in obj.data.vertices]
    widest = max(max(xs) - min(xs), max(ys) - min(ys))
    scale = WIDTH / widest
    if MAX_HEIGHT and (max(zs) - min(zs)) * scale > MAX_HEIGHT:
        scale = MAX_HEIGHT / (max(zs) - min(zs))  # a tall look (a spire, a slab on end) isn't scaled up by its width
    obj.data.transform(Matrix.Diagonal((scale, scale, scale, 1.0)) @
                       Matrix.Translation((-(min(xs) + max(xs)) / 2, -(min(ys) + max(ys)) / 2, -min(zs))))
    # Its own UVs become "grain" (what its imported maps sit on); the shared atlas is laid out by atlas_uvs.
    obj.data.uv_layers[0].name = "grain"
    for material in obj.data.materials:
        for n in material.node_tree.nodes:
            if n.type == 'TEX_IMAGE' and not n.inputs["Vector"].links:
                uv = material.node_tree.nodes.new("ShaderNodeUVMap")
                uv.uv_map = "grain"
                material.node_tree.links.new(uv.outputs["UV"], n.inputs["Vector"])
            if n.type == 'NORMAL_MAP':
                n.uv_map = "grain"
        # Height for parallax: the generated maps have none, so crevices (occlusion of the shape itself) are low.
        crevice = material.node_tree.nodes.new("ShaderNodeAmbientOcclusion")
        crevice.only_local = True
        crevice.samples = 16
        crevice.inputs["Distance"].default_value = WIDTH * 0.04
        lift = material.node_tree.nodes.new("NodeReroute")
        material.node_tree.links.new(crevice.outputs["AO"], lift.inputs[0])
        lift.label = "SH Height"
        # Metallic from the ORM's blue, for the ORM bake (prop_bake reads an "SH Metal" node).
        bsdf = next((n for n in material.node_tree.nodes if n.type == 'BSDF_PRINCIPLED'), None)
        metal_out = None
        if bsdf is not None and bsdf.inputs["Metallic"].links and METAL_FLOOR is not None:
            remap = material.node_tree.nodes.new("ShaderNodeMapRange")
            remap.inputs["From Min"].default_value = METAL_FLOOR
            remap.inputs["From Max"].default_value = 1.0
            remap.clamp = True
            material.node_tree.links.new(bsdf.inputs["Metallic"].links[0].from_socket, remap.inputs["Value"])
            metal_out = remap.outputs["Result"]
            above = look_value(key, "metal_above")
            if above is not None:
                # The look's metallic can't tell ore from rock (UltraTex made Iron B all metal): only what is above
                # this fraction of the height (its crystal crown) stays metal.
                tree = material.node_tree
                position = tree.nodes.new("ShaderNodeNewGeometry")
                xyz = tree.nodes.new("ShaderNodeSeparateXYZ")
                tree.links.new(position.outputs["Position"], xyz.inputs["Vector"])
                crown = tree.nodes.new("ShaderNodeMapRange")
                height = (max(zs) - min(zs)) * scale
                crown.inputs["From Min"].default_value = height * (above - 0.04)
                crown.inputs["From Max"].default_value = height * (above + 0.04)
                crown.clamp = True
                tree.links.new(xyz.outputs["Z"], crown.inputs["Value"])
                masked = tree.nodes.new("ShaderNodeMath")
                masked.operation = 'MULTIPLY'
                tree.links.new(metal_out, masked.inputs[0])
                tree.links.new(crown.outputs["Result"], masked.inputs[1])
                metal_out = masked.outputs["Value"]
            tag = material.node_tree.nodes.new("NodeReroute")
            strength = manifest_value("metal_strength")
            if strength is not None:
                # A crystal is mostly glass with a metallic sheen: fully metal, Moonsilver's pale crystals mirrored the
                # dark ground through the follow-the-player reflection probe and read dark grey in game. The mask
                # (metal_out) still places the ore's polish, its glow and the darkened rock; only metallic is scaled.
                scaled = material.node_tree.nodes.new("ShaderNodeMath")
                scaled.operation = 'MULTIPLY'
                scaled.inputs[1].default_value = strength
                material.node_tree.links.new(metal_out, scaled.inputs[0])
                material.node_tree.links.new(scaled.outputs["Value"], tag.inputs[0])
            else:
                material.node_tree.links.new(metal_out, tag.inputs[0])
            tag.label = "SH Metal"
            if DIELECTRIC_DARKEN > 0 and bsdf.inputs["Base Color"].links:
                tree = material.node_tree
                lost = tree.nodes.new("ShaderNodeMath")  # m * (1 - r): the metal this pixel lost
                lost.operation = 'MULTIPLY'
                keep = tree.nodes.new("ShaderNodeMath")
                keep.operation = 'SUBTRACT'
                keep.inputs[0].default_value = 1.0
                tree.links.new(metal_out, keep.inputs[1])
                tree.links.new(bsdf.inputs["Metallic"].links[0].from_socket, lost.inputs[0])
                tree.links.new(keep.outputs["Value"], lost.inputs[1])
                factor = tree.nodes.new("ShaderNodeMath")  # 1 - k * lost
                factor.operation = 'MULTIPLY_ADD'
                tree.links.new(lost.outputs["Value"], factor.inputs[0])
                factor.inputs[1].default_value = -DIELECTRIC_DARKEN
                factor.inputs[2].default_value = 1.0
                darken = tree.nodes.new("ShaderNodeMix")
                darken.data_type = 'RGBA'
                darken.blend_type = 'MULTIPLY'
                darken.inputs["Factor"].default_value = 1.0
                tree.links.new(bsdf.inputs["Base Color"].links[0].from_socket, darken.inputs["A"])
                tree.links.new(factor.outputs["Value"], darken.inputs["B"])
                tree.links.new(darken.outputs["Result"], bsdf.inputs["Base Color"])
        lift = manifest_value("ore_brighten")
        if bsdf is not None and lift and metal_out is not None and bsdf.inputs["Base Color"].links:
            # The ore's colour times lift where the ore is (Moonsilver's "pale" crystals were a mid grey, 0.6).
            tree = material.node_tree
            factor = tree.nodes.new("ShaderNodeMath")  # 1 + (lift - 1) * mask
            factor.operation = 'MULTIPLY_ADD'
            tree.links.new(metal_out, factor.inputs[0])
            factor.inputs[1].default_value = lift - 1.0
            factor.inputs[2].default_value = 1.0
            brighten = tree.nodes.new("ShaderNodeMix")
            brighten.data_type = 'RGBA'
            brighten.blend_type = 'MULTIPLY'
            brighten.inputs["Factor"].default_value = 1.0
            tree.links.new(bsdf.inputs["Base Color"].links[0].from_socket, brighten.inputs["A"])
            tree.links.new(factor.outputs["Value"], brighten.inputs["B"])
            tree.links.new(brighten.outputs["Result"], bsdf.inputs["Base Color"])
        if bsdf is not None and ROUGHNESS:
            set_roughness(material.node_tree, bsdf, metal_out)
    for poly in obj.data.polygons:
        poly.use_smooth = True
    return obj


def set_roughness(tree, bsdf, metal_out):
    """Roughness into the asset's ranges (manifest roughness: {"rock": [lo, hi], "ore": [lo, hi]}), keeping the
    generated variation inside them. UltraTex makes rock and wood glossy (Iron's rock 0.2, Sticks 0.27: wet-looking) and
    copper a mirror (0.02), which shows only a pin-point sun glint; matte rock with polished but not mirror ore catches
    the sun, the moon and torches as broad highlights on the metal alone."""
    socket = bsdf.inputs["Roughness"]
    source = socket.links[0].from_socket if socket.links else None

    def ranged(lo, hi):
        node = tree.nodes.new("ShaderNodeMapRange")
        node.inputs["To Min"].default_value = lo
        node.inputs["To Max"].default_value = hi
        if source is not None:
            tree.links.new(source, node.inputs["Value"])
        else:
            node.inputs["Value"].default_value = socket.default_value
        return node.outputs["Result"]

    rock = ranged(*ROUGHNESS["rock"])
    if "ore" in ROUGHNESS and metal_out is not None:
        blend = tree.nodes.new("ShaderNodeMix")
        blend.data_type = 'FLOAT'
        tree.links.new(metal_out, blend.inputs["Factor"])
        tree.links.new(rock, blend.inputs["A"])
        tree.links.new(ranged(*ROUGHNESS["ore"]), blend.inputs["B"])
        rock = blend.outputs["Result"]
    tree.links.new(rock, socket)


def emission_from_albedo(glow):
    """An emission map from the baked albedo: where it is close to glow["colour"] (hue mode, by direction in RGB, so
    brightness doesn't matter) or bright (bright mode), above glow["threshold"], tinted glow["tint"]."""
    folder = os.path.join(ART, NAME)
    albedo = bpy.data.images.load(os.path.join(folder, f"{NAME}_Albedo.png"))
    w, h = albedo.size
    px = numpy.empty(w * h * 4, dtype=numpy.float32)
    albedo.pixels.foreach_get(px)
    rgb = px.reshape(-1, 4)[:, :3]
    if glow["mode"] == "hue":
        # Closeness by hue angle (1 = same hue, 0 = opposite): a direction in RGB can't tell yellow-green moss from a
        # green glow (cosine ~0.93), the hue wheel can (~55 degrees apart).
        def hue(c):
            c = numpy.atleast_2d(c)
            hi, lo = c.max(axis=1), c.min(axis=1)
            d = hi - lo + 1e-5
            r, g, b = c[:, 0], c[:, 1], c[:, 2]
            h = numpy.where(hi == r, ((g - b) / d) % 6, numpy.where(hi == g, (b - r) / d + 2, (r - g) / d + 4))
            return h * 60.0
        dh = numpy.abs(hue(rgb) - hue(numpy.array(glow["colour"], dtype=numpy.float32))[0])
        closeness = 1.0 - numpy.minimum(dh, 360.0 - dh) / 180.0
        brightness = rgb.max(axis=1)
        saturation = (brightness - rgb.min(axis=1)) / (brightness + 1e-4)
        # Only what is lit: bright and strongly coloured (a glowing seam), not rock or moss that is merely that hue.
        bright = numpy.clip((brightness - glow.get("min_brightness", 0.45)) / 0.25, 0, 1)
        vivid = numpy.clip((saturation - glow.get("min_saturation", 0.35)) / 0.25, 0, 1)
        strength = numpy.clip((closeness - glow["threshold"]) / (1.0 - glow["threshold"]), 0, 1) * bright * vivid
    elif glow["mode"] == "metal":
        # Where the ore is metal (the ORM's blue, baked at half size: scaled up to the albedo's), in its own colour.
        orm = bpy.data.images.load(os.path.join(folder, f"{NAME}_ORM.png"))
        orm.colorspace_settings.name = 'Non-Color'
        orm.scale(w, h)
        metal = numpy.empty(w * h * 4, dtype=numpy.float32)
        orm.pixels.foreach_get(metal)
        metallic = metal.reshape(-1, 4)[:, 2]
        strength = numpy.clip((metallic - glow["threshold"]) / (1.0 - glow["threshold"]), 0, 1)
        own = rgb / (rgb.max(axis=1, keepdims=True) + 1e-4)  # the metal's own hue at full brightness
        tint = numpy.array(glow["tint"], dtype=numpy.float32)
        out = numpy.zeros((w * h, 4), dtype=numpy.float32)
        out[:, :3] = strength[:, None] * (own * 0.5 + tint[None, :] * 0.5)
        out[:, 3] = 1.0
        save_emission(out, w, h, folder)
        return
    else:
        luminance = rgb @ numpy.array([0.2126, 0.7152, 0.0722], dtype=numpy.float32)
        strength = numpy.clip((luminance - glow["threshold"]) / (1.0 - glow["threshold"]), 0, 1)
    tint = numpy.array(glow["tint"], dtype=numpy.float32)
    out = numpy.zeros((w * h, 4), dtype=numpy.float32)
    out[:, :3] = strength[:, None] * tint[None, :]
    out[:, 3] = 1.0
    save_emission(out, w, h, folder)


def save_emission(out, w, h, folder):
    img = bpy.data.images.new(f"{NAME}_Emission", w, h, alpha=False)
    img.colorspace_settings.name = 'sRGB'
    img.pixels.foreach_set(out.ravel())
    img.filepath_raw = os.path.join(folder, f"{NAME}_Emission.png")
    img.file_format = 'PNG'
    img.save()
    no_moss_where_glowing(out, w, h, folder)


def no_moss_where_glowing(out, w, h, folder):
    """Clear the BlendMask's coverage (alpha: where the live moss grows) wherever the emission glows: the coverage is
    baked from up-facing surfaces, so moss grew in blotches on the Radiant Life Orb's glowing orb."""
    path = os.path.join(folder, f"{NAME}_BlendMask.png")
    if not os.path.exists(path):
        return
    mask = bpy.data.images.load(path)
    mask.colorspace_settings.name = 'Non-Color'
    mw, mh = mask.size
    px = numpy.empty(mw * mh * 4, dtype=numpy.float32)
    mask.pixels.foreach_get(px)
    px = px.reshape(mh, mw, 4)
    glow = out[:, :3].max(axis=1).reshape(h, w)
    sy, sx = h // mh, w // mw
    glow = glow[:mh * sy, :mw * sx].reshape(mh, sy, mw, sx).max(axis=(1, 3))  # the mask is half size
    px[:, :, 3] *= numpy.clip(1.0 - glow * 6.0, 0.0, 1.0)
    mask.pixels.foreach_set(px.ravel())
    mask.save()


def main():
    bpy.ops.wm.read_factory_settings(use_empty=True)
    coll = collection(NAME)

    def builder(c):
        return [import_look(path, chr(65 + k), TURNS[k] if k < len(TURNS) else 0.0, c) for k, path in enumerate(GLBS)]

    looks = make_asset(NAME, builder, 2048, coll, cavity_distance=0.15, collider=True, lods=(0.5, 0.2))
    if GLOW:
        emission_from_albedo(GLOW)
    stage([(looks, WIDTH * 1.4)], row_spacing=WIDTH)
    camera((0.0, -WIDTH * 2.6, WIDTH * 2.4), (0.0, 0.0, WIDTH * 0.2), lens=40)
    render(os.path.join(os.path.dirname(GLBS[0]), f"{NAME} ingest preview.png"), 1600, 900)
    print("INGEST DONE", NAME, [o.name for o in looks])


if __name__ == "__main__":
    main()
